# setup_default_parameters ----
## Setup ----
data <- FIMS::FIMSFrame(data_big)

## IO correctness ----
test_that("`setup_default_parameters()` works with correct inputs", {
  result <- setup_default_parameters(data = data)

  #' @description Test that output is a `tbl_df`.
  expect_s3_class(result, "tbl_df")

  #' @description Test that output has the expected column structure.
  expect_equal(
    colnames(result),
    c(
      "module_name", "fleet", "module_type", "label",
      "age", "length", "timing", "value", "estimation_type",
      "distribution_type", "distribution"
    )
  )

  #' @description Test that key modules are included in the output.
  expect_true(all(c(
    "Fleet", "Selectivity", "Recruitment", "Maturity", "Growth", "Population"
  ) %in% unique(result[["module_name"]])))

  #' @description Test that output includes at least one configured parameter row.
  expect_gt(nrow(result), 0)

  clear()

  #' @description Test that the generated parameter values have not changed from the accepted snapshot.
  expect_snapshot_file(
    save_csv(result),
    "default_parameters.csv",
    compare = compare_file_text
  )
})

test_that("`setup_default_parameters()` defaults to EWAA when empirical weight-at-age is present", {
  result <- setup_default_parameters(data = data)

  growth_type <- result |>
    dplyr::filter(.data[["module_name"]] == "Growth") |>
    dplyr::pull(.data[["module_type"]]) |>
    unique()

  #' @description Test that empirical weight-at-age data keep the default Growth module as EWAA.
  expect_equal(growth_type, "EWAA")

  clear()
})

test_that("`setup_default_parameters()` defaults to VonB-Schnute when weight-at-age is absent and length compositions are present", {
  data_without_weight_at_age <- FIMS::FIMSFrame(
    dplyr::filter(data_big, type != "weight_at_age")
  )

  result <- setup_default_parameters(data = data_without_weight_at_age)

  growth_type <- result |>
    dplyr::filter(.data[["module_name"]] == "Growth") |>
    dplyr::pull(.data[["module_type"]]) |>
    unique()

  #' @description Test that length-composition data trigger VonB-Schnute when empirical weight-at-age data are absent.
  expect_equal(growth_type, "VonB-Schnute")

  clear()
})

test_that("`setup_default_parameters()` errors when neither weight-at-age nor length compositions are present", {
  data_without_growth_information <- FIMS::FIMSFrame(
    dplyr::filter(
      data_big,
      !type %in% c("weight_at_age", "length_comp")
    )
  )

  #' @description Test that FIMS does not silently choose a default Growth module without empirical weight-at-age or length-composition data.
  expect_error(
    setup_default_parameters(data = data_without_growth_information),
    regexp = "cannot choose a default Growth module"
  )

  clear()
})

test_that("modular pipeline matches `setup_default_parameters()`", {
  fleet1_name <- "fleet1"

  fleet1_selectivity_defaults <- setup_default_Selectivity(
    data = data,
    fleet = fleet1_name
  )

  fleet1_fleet_defaults <- setup_default_Fleet(
    data = data,
    fleet = fleet1_name
  )

  survey1_name <- "survey1"

  survey1_selectivity_defaults <- setup_default_Selectivity(
    data = data,
    fleet = survey1_name
  )

  survey1_fleet_defaults <- setup_default_Fleet(
    data = data,
    fleet = survey1_name
  )

  recruitment_defaults <- setup_default_Recruitment(data = data)
  maturity_defaults <- setup_default_Maturity(data = data)
  growth_defaults <- setup_default_Growth()

  log_M <- log(0.2)
  log_rzero <- recruitment_defaults |>
    dplyr::filter(.data[["label"]] == "log_rzero") |>
    dplyr::pull(.data[["value"]])
  population_defaults <- setup_default_Population(
    data = data,
    log_M = log_M,
    log_init_naa = FIMS:::setup_default_log_init_naa(
      n_ages = get_n_ages(data),
      log_rzero = log_rzero,
      log_M = log_M
    )
  )

  modular_result <- dplyr::bind_rows(
    fleet1_selectivity_defaults,
    fleet1_fleet_defaults,
    survey1_selectivity_defaults,
    survey1_fleet_defaults,
    recruitment_defaults,
    maturity_defaults,
    growth_defaults,
    population_defaults
  )

  expected_result <- setup_default_parameters(data = data)

  #' @description Test that the modular pipeline output is identical to `setup_default_parameters()`.
  expect_equal(
    modular_result |>
      dplyr::arrange(dplyr::across(dplyr::everything())),
    expected_result |>
      dplyr::arrange(dplyr::across(dplyr::everything()))
  )

  clear()
})

test_that("modular pipeline with `purrr` matches `setup_default_parameters()`", {
  model_data <- get_data(data)
  fleets <- model_data |>
    dplyr::pull(.data[["fleet"]]) |>
    na.omit() |>
    unique()

  fleet_defaults <- purrr::map(
    fleets,
    function(fleet_i) {
      setup_default_Fleet(data = data, fleet = fleet_i)
    }
  ) |>
    dplyr::bind_rows()

  selectivity_defaults <- purrr::map(
    fleets,
    function(fleet_i) {
      setup_default_Selectivity(data = data, fleet = fleet_i)
    }
  ) |>
    dplyr::bind_rows()

  recruitment_defaults <- setup_default_Recruitment(data = data)
  maturity_defaults <- setup_default_Maturity(data = data)
  growth_defaults <- setup_default_Growth()

  log_M <- log(0.2)
  log_rzero <- recruitment_defaults |>
    dplyr::filter(.data[["label"]] == "log_rzero") |>
    dplyr::pull(.data[["value"]])
  log_init_naa <- FIMS:::setup_default_log_init_naa(
    n_ages = get_n_ages(data),
    log_rzero = log_rzero,
    log_M = log_M
  )

  population_defaults <- setup_default_Population(
    data = data,
    log_M = log_M,
    log_init_naa = log_init_naa
  )

  # Explicitly update log_init_naa values to mirror downstream modular workflows.
  population_defaults <- population_defaults |>
    dplyr::rows_update(
      tibble::tibble(
        label = "log_init_naa",
        age = get_ages(data),
        value = log_init_naa
      ),
      by = c("label", "age")
    )

  modular_result <- dplyr::bind_rows(
    selectivity_defaults,
    fleet_defaults,
    recruitment_defaults,
    maturity_defaults,
    growth_defaults,
    population_defaults
  )

  expected_result <- setup_default_parameters(data = data)

  #' @description Test that the modular pipeline output is identical to `setup_default_parameters()`.
  expect_true(identical(modular_result, expected_result))
  expect_equal(modular_result, expected_result)

  clear()
})

## Edge handling ----
test_that("`setup_default_parameters()` works with edge cases", {
  recruitment_without_distribution <- setup_default_Recruitment(
    data = data,
    distribution = NA_character_
  )

  #' @description Test that `log_sd` is not created when distribution is not specified.
  log_sd_value <- recruitment_without_distribution |>
    dplyr::filter(.data[["label"]] == "log_sd") |>
    dplyr::pull(.data[["value"]])

  expect_equal(log_sd_value, numeric(0))

  #' @description Test that `log_devs` estimation_type is constant when distribution is not specified.
  log_devs_value <- recruitment_without_distribution |>
    dplyr::filter(.data[["label"]] == "log_devs") |>
    dplyr::pull(.data[["estimation_type"]]) |>
    unique()

  expect_equal(log_devs_value, "constant")

  #' @description Test that `log_devs` distribution_type is `NA` when distribution is not specified.
  log_devs_distribution_type <- recruitment_without_distribution |>
    dplyr::filter(.data[["label"]] == "log_devs") |>
    dplyr::pull(.data[["distribution_type"]]) |>
    unique()

  expect_equal(log_devs_distribution_type, NA_character_)

  clear()
})

test_that("`setup_default_log_init_naa()` handles scalar and vector `log_M`", {
  n_ages <- get_n_ages(data)
  log_rzero <- log(1e+06)

  scalar_result <- FIMS:::setup_default_log_init_naa(
    n_ages = n_ages,
    log_rzero = log_rzero,
    log_M = log(0.2)
  )

  vector_log_M <- log(seq(0.15, 0.15 + (n_ages - 1) * 0.01, by = 0.01))
  vector_result <- FIMS:::setup_default_log_init_naa(
    n_ages = n_ages,
    log_rzero = log_rzero,
    log_M = vector_log_M
  )

  expected_m <- exp(vector_log_M)
  expected_vector <- log_rzero - c(0, cumsum(expected_m))[seq_len(n_ages)]
  expected_vector[n_ages] <- expected_vector[n_ages] - log(expected_m[n_ages])

  #' @description Test that scalar log_M still returns one value per age.
  expect_length(scalar_result, n_ages)
  #' @description Test that vector log_M produces expected age-specific log_init_naa values.
  expect_equal(vector_result, expected_vector)

  clear()
})

## Error handling ----
test_that("`setup_default_parameters()` returns correct error messages", {
  #' @description Test that invalid `data` class triggers an informative error.
  expect_error(
    object = setup_default_parameters(data = "not_a_fimsframe"),
    regexp = "FIMSFrame"
  )

  clear()
})

test_that("`setup_default_log_init_naa()` returns correct error messages", {
  #' @description Test that invalid log_M length triggers an informative error.
  expect_error(
    object = FIMS:::setup_default_log_init_naa(
      n_ages = get_n_ages(data),
      log_rzero = log(1e+06),
      log_M = c(log(0.2), log(0.3))
    ),
    regexp = "log_M.*single numeric value.*length equal to n_ages"
  )

  clear()
})
